cat > migrations/002_payment_webhooks.sql <<'EOF'
-- Webhook events already handled (providers deliver at-least-once).
create table payment_webhook_events (
  id text primary key,
  type text not null,
  payment_id text not null,
  created bigint not null,
  received_at timestamptz not null default now()
);

-- Timestamp (provider `created`, unix seconds) of the last webhook event applied to the order,
-- so late or out-of-order deliveries never overwrite newer state.
alter table orders add column status_event_created bigint;
create index orders_payment_id_idx on orders (payment_id);
EOF
python3 - <<'EOF'
p='src/app.ts'
s=open(p).read()
s=s.replace('import { pool } from "./db.ts";','import { createHmac, timingSafeEqual } from "node:crypto";\nimport { pool } from "./db.ts";\nimport { webhookSecret } from "./payments.ts";',1)
s=s.replace('''  app.use(express.json());
''','''
  // Webhooks are authenticated by signature, not bearer token, and need the raw body to verify it.
  app.post(
    "/webhooks/payments",
    express.raw({ type: "*/*", limit: "100kb" }),
    async (req: Request, res: Response) => {
      const raw: Buffer = Buffer.isBuffer(req.body) ? req.body : Buffer.alloc(0);
      const given = req.get("provider-signature") ?? "";
      const expected = createHmac("sha256", webhookSecret).update(raw).digest();
      const givenBuf = Buffer.from(given, "hex");
      if (givenBuf.length !== expected.length || !timingSafeEqual(givenBuf, expected)) {
        return sendError(res, 401, "invalid_signature", "Invalid webhook signature");
      }

      let event: { id?: unknown; type?: unknown; paymentId?: unknown; created?: unknown };
      try {
        event = JSON.parse(raw.toString("utf8"));
      } catch {
        return sendError(res, 400, "invalid_body", "Body must be JSON");
      }
      const { id, type, paymentId, created } = event ?? {};
      if (typeof id !== "string" || typeof type !== "string" || typeof paymentId !== "string" || !Number.isInteger(created)) {
        return sendError(res, 400, "invalid_body", "Expected id, type, paymentId and integer created");
      }
      const status = WEBHOOK_STATUS[type];
      if (!status) return res.json({ ok: true, ignored: true }); // unknown event type: acknowledge

      const client = await pool.connect();
      try {
        await client.query("begin");
        const seen = await client.query(
          "insert into payment_webhook_events (id, type, payment_id, created) values ($1, $2, $3, $4) on conflict (id) do nothing",
          [id, type, paymentId, created],
        );
        if (seen.rowCount === 0) {
          await client.query("rollback");
          return res.json({ ok: true, duplicate: true });
        }
        // Lock the order row; only apply if this event is not older than the last one applied.
        const order = await client.query("select id from orders where payment_id = $1 for update", [paymentId]);
        if (order.rowCount === 0) {
          await client.query("rollback");
          // Not recorded, so the provider's retry can succeed once the order has its payment id.
          return sendError(res, 404, "unknown_payment", "No order for this payment");
        }
        await client.query(
          `update orders set status = $2, status_event_created = $3
           where payment_id = $1 and (status_event_created is null or status_event_created <= $3)`,
          [paymentId, status, created],
        );
        await client.query("commit");
        res.json({ ok: true });
      } catch (err) {
        await client.query("rollback").catch(() => {});
        throw err;
      } finally {
        client.release();
      }
    },
  );

  app.use(express.json());
''',1)
s=s.replace('export function createApp','const WEBHOOK_STATUS: Record<string, string> = {\n  "charge.succeeded": "paid",\n  "charge.failed": "failed",\n  "charge.refunded": "refunded",\n};\n\nexport function createApp',1)
open(p,'w').write(s)
EOF
sed -i '' 's/pending | paid | refunded/pending | paid | failed | refunded/' migrations/001_init.sql
cat >> test/app.test.ts <<'EOF'

import { createHmac } from "node:crypto";
import { webhookSecret } from "../src/payments.ts";

const hook = (event: object, signature?: string) => {
  const body = JSON.stringify(event);
  return fetch(`${base}/webhooks/payments`, {
    method: "POST",
    headers: {
      "content-type": "application/json",
      "provider-signature": signature ?? createHmac("sha256", webhookSecret).update(body).digest("hex"),
    },
    body,
  });
};
const status = async (id: number) => (await pool.query("select status from orders where id = $1", [id])).rows[0].status;

test("webhook rejects bad signatures", async () => {
  const res = await hook({ id: "evt_bad", type: "charge.failed", paymentId: "pay_seed_1", created: 1 }, "00");
  assert.equal(res.status, 401);
  assert.equal(await status(1), "paid");
});

test("webhook updates status, ignores duplicates and stale events", async () => {
  const e = { id: "evt_1", type: "charge.refunded", paymentId: "pay_seed_3", created: 2000 };
  assert.equal((await hook(e)).status, 200);
  assert.equal(await status(3), "refunded");
  // late older event must not overwrite
  assert.equal((await hook({ id: "evt_0", type: "charge.succeeded", paymentId: "pay_seed_3", created: 1000 })).status, 200);
  assert.equal(await status(3), "refunded");
  assert.deepEqual(await (await hook(e)).json(), { ok: true, duplicate: true });
  assert.equal((await hook({ id: "evt_x", type: "charge.failed", paymentId: "nope", created: 1 })).status, 404);
});
EOF
